"""Original motor-neuron disease chapter."""
from qbank_authoring import question,ref,finalize
GC=ref('Gold Coast ALS Criteria and Role of EMG','https://pmc.ncbi.nlm.nih.gov/articles/PMC9120398/')
EA=ref('EAN/ERN EURO-NMD ALS Management Guideline, 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11235832/')
PA=ref('PACTALS Management Guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC12465052/')
KE=ref('GeneReviews: Spinal and Bulbar Muscular Atrophy','https://www.ncbi.nlm.nih.gov/books/NBK1333/')
TO=ref('FDA Drug Trials Snapshot: QALSODY','https://www.fda.gov/drugs/drug-trials-snapshots/drug-trials-snapshots-qalsody')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))

q('Progressive hand weakness and wasting coexist with brisk leg reflexes and extensor plantar responses, while sensation is largely preserved. Which syndrome is most concerning?', 'A motor-neuron disorder such as ALS after appropriate exclusion of mimics',[
 ('Pure sensory polyneuropathy','The mixed upper and lower motor findings with preserved sensation do not fit.'),('MG as the complete explanation','MG does not explain pathological plantar responses and neurogenic wasting.'),('A benign fasciculation syndrome established from one sign','Progressive objective weakness and upper motor signs are not benign fasciculation alone.')],
 'Recognize combined motor-system dysfunction', '**ALS can involve both upper and lower motor neurons in a progressive syndrome.**', ['Weakness may begin focally and spread.','Prominent sensory or sphincter findings should prompt a careful alternative assessment.'], '**Exclude treatable mimics.**', ['Cervical myelopathy and immune motor neuropathies are important.','The diagnosis requires clinical integration, not one sign.'], [['LMN','Wasting and denervation'],['UMN','Pathological reflexes/spasticity'],['Diagnosis','Progression and mimic exclusion']], [GC], 'clinical_scenario')
q('Under Gold Coast criteria, which motor-neuron distribution can support ALS diagnosis when progression and exclusion requirements are fulfilled?', 'UMN and LMN dysfunction in at least one region, or LMN dysfunction in at least two regions',[
 ('A single isolated fasciculation without progression','This does not meet the required syndrome.'),('Sensory loss alone in two regions','These are motor-neuron criteria.'),('An abnormal MRI alone without a motor syndrome','Imaging helps exclude alternatives but is not sufficient.')],
 'Use a specified diagnostic framework', '**Gold Coast criteria require progressive motor impairment after previously normal motor function.**', ['The UMN/LMN distribution is assessed clinically and with appropriate EMG evidence.','Investigations must exclude other plausible disease processes.'], '**Do not reduce criteria to a checklist detached from examination.**', ['Bulbar, cervical, thoracic and lumbosacral regions are considered.','The quality of the clinical diagnosis remains central.'], [['Progression','Required'],['Motor distribution','Defined regional pattern'],['Exclusion','Required investigations']], [GC])
q('Which EMG combination supports lower motor neuron dysfunction in the ALS diagnostic framework?', 'Chronic neurogenic motor-unit change together with ongoing denervation in an appropriate distribution',[
 ('Increased jitter alone as specific ALS proof','Jitter is not unique to ALS.'),('Short small units with early recruitment as the defining pattern','This more often supports myopathy.'),('Sensory slowing alone','This does not establish LMN degeneration.')],
 'EMG complements the clinical examination', '**Chronic neurogenic change and active denervation provide evidence of motor-unit injury.**', ['Fibrillations, positive sharp waves and suitable fasciculation findings can contribute.','Sampling distribution matters.'], '**Do not demand a positive EMG in every muscle.**', ['Sensitivity is imperfect, particularly in selected bulbar or UMN-predominant cases.','Interpret with progression and alternatives.'], [['Chronic change','Reinnervation'],['Ongoing denervation','Active LMN injury'],['Distribution','Supports regional assessment']], [GC])
q('A patient reports occasional calf fasciculations but has normal strength and no progressive functional change. What is the best interpretation?', 'Fasciculations alone are insufficient to diagnose ALS',[
 ('Every fasciculation proves motor-neuron degeneration','Benign and other causes occur.'),('A normal examination guarantees that no follow-up is ever needed','Evolution or new objective symptoms can change the assessment.'),('Fasciculations must be a primary psychiatric symptom','They are real motor phenomena with several causes.')],
 'A sign is not a syndrome', '**ALS diagnosis depends on progressive motor impairment and associated findings.**', ['Exercise, medicines and benign syndromes can produce fasciculations.','The history and objective examination determine concern.'], '**Use proportionate evaluation and follow-up.**', ['Assess new weakness, wasting or bulbar symptoms.','Avoid a devastating label from an isolated finding.'], [['Fasciculation alone','Nonspecific'],['Progressive weakness','Raises concern'],['Action','Clinical context and follow-up']], [GC], 'clinical_scenario')
q('Tongue wasting and fasciculations accompany dysarthria and dysphagia. Which motor component is particularly evident?', 'Bulbar lower motor neuron dysfunction',[
 ('A pure corticobulbar UMN syndrome without LMN involvement','Tongue atrophy and fasciculations favor LMN involvement.'),('An isolated sensory neuropathy','This does not account for tongue motor wasting.'),('A visual pathway lesion','This does not localize the findings.')],
 'Bulbar weakness can have upper and lower motor components', '**Atrophy and fasciculation identify an LMN contribution.**', ['A brisk jaw jerk or spastic speech can indicate accompanying UMN disease.','MG and structural lesions remain differential considerations.'], '**Assess swallowing and breathing directly.**', ['Aspiration and nutritional loss can develop early.','A neurological diagnosis does not replace a practical safety plan.'], [['Tongue atrophy','LMN clue'],['Brisk jaw jerk','UMN clue'],['Care priority','Swallowing and respiratory function']], [GC,EA], 'clinical_scenario')
q('Inappropriate episodes of laughing or crying occur in a patient with ALS and do not match their underlying mood. Which syndrome is most likely?', 'Pseudobulbar affect',[
 ('Major depression is proven by crying alone','Mood disorder and emotional lability are different, though they can coexist.'),('Loss of consciousness due to epilepsy in every case','The described emotional expression does not establish a seizure.'),('Deliberate behavior as the required explanation','The syndrome can arise from neurological network dysfunction.')],
 'Expression and internal mood can dissociate', '**Pseudobulbar affect causes involuntary disproportionate emotional expression.**', ['Ask about the subjective emotional experience.','Assess coexisting depression or anxiety separately.'], '**Offer explanation and symptomatic treatment where appropriate.**', ['Medication options depend on availability, interactions and contraindications.','Caregiver understanding can reduce distress.'], [['Pseudobulbar affect','Involuntary expression'],['Depression','Sustained mood syndrome'],['Assessment','Both can coexist']], [EA], 'clinical_scenario')
q('Which cognitive-behavioral association is recognized in ALS?', 'A frontotemporal spectrum disorder in a subset of patients',[
 ('Cognition must be normal in every ALS patient','Executive, language and behavioral changes can occur.'),('Every ALS patient has severe dementia at diagnosis','The spectrum is variable.'),('Any mild forgetfulness excludes ALS','Cognitive symptoms require assessment rather than automatic exclusion.')],
 'Motor-neuron disease can extend beyond motor pathways', '**ALS and FTD have clinical and biological overlap.**', ['Executive or behavioral changes can influence adherence and communication.','Some genetic forms have a strong ALS-FTD association.'], '**Assess cognition and behavior in care planning.**', ['Support decision-making and caregiver needs.','Do not assume a diagnosis automatically removes capacity.'], [['Spectrum','ALS to ALS-FTD'],['Care effect','Planning and adherence'],['Capacity','Decision-specific assessment']], [EA])
q('Which finding should particularly prompt investigation of a treatable ALS mimic?', 'Focal motor conduction block outside common entrapment sites',[
 ('Progressive mixed UMN and LMN signs as the only finding','This can fit ALS after exclusion of mimics.'),('Normal sensation alone','This is compatible with ALS and MMN.'),('A mildly raised CK as definitive proof against ALS','Modest CK elevations can occur in neurogenic disease.')],
 'Recognize the immune motor-neuropathy alternative', '**MMN can produce asymmetric weakness and fasciculations but may respond to IVIG.**', ['Motor block and nerve-territory patterns are important clues.','Upper motor neuron signs are not typical of MMN.'], '**Check the electrophysiology rather than relying on appearance.**', ['Avoid overlooking a treatable disorder.','Interpret technical and entrapment-related findings carefully.'], [['MMN clue','Nonentrapment motor block'],['ALS clue','UMN plus LMN spread'],['Treatment implication','Potential immune-responsive mimic']], [GC,EA])
q('Hand wasting and brisk leg reflexes coexist with neck pain and a sensory level. What alternative requires assessment before attributing the syndrome to ALS?', 'Cervical cord compression with segmental root or anterior-horn involvement',[
 ('A sensory level is required for ALS','It instead suggests a cord process.'),('Neck imaging is unnecessary if fasciculations are present','Structural disease can produce LMN findings at the lesion.'),('All cervical spondylosis on imaging proves causality','Imaging must match the clinical anatomy.')],
 'One structural lesion can produce mixed motor signs', '**A cervical lesion can cause LMN signs at the level and UMN signs below it.**', ['Sensory and sphincter findings strengthen a cord differential.','Degenerative imaging can also be incidental.'], '**Use anatomically correlated MRI assessment.**', ['Urgency depends on deficits and progression.','Do not let an incidental finding explain unrelated bulbar or widespread signs automatically.'], [['At lesion','Segmental LMN findings'],['Below lesion','Long-tract findings'],['Causality','Clinical-imaging correlation']], [GC], 'clinical_scenario')
q('A man has slowly progressive bulbar and limb LMN weakness, tremor, gynecomastia and reduced fertility. Which diagnosis is most characteristic?', 'Spinal and bulbar muscular atrophy, Kennedy disease',[
 ('Typical ALS as the uniquely required diagnosis','Androgen-insensitivity features and slow course suggest SBMA.'),('Myotonic dystrophy type 1 as the best fit without myotonia','The LMN and androgen phenotype points elsewhere.'),('AQP4-NMOSD','The clinical pattern is not a CNS inflammatory attack syndrome.')],
 'Endocrine features can identify a motor-neuron mimic', '**SBMA is caused by an androgen-receptor CAG expansion.**', ['It is X-linked and mainly affects males.','Sensory nerve abnormalities may accompany the motor syndrome.'], '**Confirm genetically and counsel the family.**', ['The natural history and management differ from ALS.','Assess swallowing, respiration and metabolic health.'], [['Gene','AR CAG expansion'],['Clue','Androgen insensitivity'],['Pattern','Slow LMN disease']], [KE], 'clinical_scenario')
q('What inheritance pattern characterizes Kennedy disease?', 'X-linked inheritance involving an expanded androgen-receptor CAG repeat',[
 ('Autosomal dominant HTT expansion','That causes Huntington disease.'),('Mitochondrial inheritance in every family','This is not the SBMA mechanism.'),('Autosomal recessive FXN expansion','That causes Friedreich ataxia.')],
 'A repeat expansion can cause several distinct neurological diseases', '**The AR expansion produces a polyglutamine-associated disorder.**', ['Male expression relates to the androgen context.','Family histories may be incomplete.'], '**Use targeted genetic counseling.**', ['Discuss carrier and reproductive implications.','Avoid inferring an exact individual course from repeat size alone.'], [['Kennedy','AR, X-linked'],['Huntington','HTT, autosomal dominant'],['Friedreich','FXN, autosomal recessive']], [KE])
q('What is the appropriate general approach to genetic testing in ALS?', 'Offer informed genetic counseling and suitable testing, including discussion with patients who lack an obvious family history',[
 ('No family history excludes a pathogenic variant','Apparently sporadic disease can have an identifiable genetic cause.'),('Every positive variant has the same treatment implication','Pathogenicity, penetrance and gene-specific therapies differ.'),('Testing removes the need for consent discussion','Results can affect patients and relatives substantially.')],
 'Genetic information can affect care and family planning', '**Family history alone does not capture all genetic ALS.**', ['C9orf72, SOD1 and other genes are relevant.','Testing methods must detect the relevant variant types, including expansions when indicated.'], '**Explain uncertainty and consequences.**', ['A variant of uncertain significance is not automatically causal.','Discuss family communication and gene-specific options appropriately.'], [['Family history','Useful but incomplete'],['Result','Pathogenicity matters'],['Care','May inform targeted options']], [EA,PA])
q('Which disease-modifying drug is broadly recommended at ALS diagnosis when appropriate and tolerated?', 'Riluzole',[
 ('Pyridostigmine as routine disease modification','This treats transmission disorders rather than ALS progression.'),('Interferon beta as standard ALS therapy','This is not the established ALS recommendation.'),('High-dose chronic prednisone in every ALS patient','Routine immunosuppression has not established this benefit.')],
 'Offer evidence-based disease modification with realistic expectations', '**Riluzole provides a modest benefit and is commonly offered from diagnosis.**', ['The EAN guideline recommends ongoing treatment when tolerated.','Assess adverse effects and liver monitoring according to the label.'], '**Explain what treatment cannot promise.**', ['It does not reliably restore lost strength.','Multidisciplinary supportive care remains essential.'], [['Drug','Riluzole'],['Benefit','Modest disease-course benefit'],['Monitoring','Tolerance and product guidance']], [EA,PA])
q('Tofersen is a gene-targeted treatment for which ALS subgroup?', 'ALS associated with a pathogenic SOD1 mutation',[
 ('Every C9orf72 expansion carrier regardless of syndrome','Tofersen targets a different gene.'),('All acquired immune motor neuropathies','It is not a generic motor-weakness therapy.'),('All patients with fasciculations before diagnostic assessment','A defined genetic and clinical indication is required.')],
 'A targeted drug needs a matching molecular diagnosis', '**Tofersen is an antisense oligonucleotide that reduces SOD1 protein production.**', ['It is administered intrathecally.','The US accelerated approval used a biomarker-based pathway.'], '**Discuss the evidence and procedural risks.**', ['Eligibility and access vary by jurisdiction.','Monitor according to current prescribing guidance.'], [['Target','SOD1'],['Route','Intrathecal'],['Selection','Confirmed relevant mutation']], [TO,EA])
q('How should edaravone be discussed in ALS care?', 'As a jurisdiction- and patient-specific option with differing guideline recommendations, rather than a guaranteed universal benefit',[
 ('As a complete cure for every ALS phenotype','This is unsupported.'),('As a substitute for ventilation and nutrition planning','Supportive care remains necessary.'),('As identical in indication and evidence to tofersen','The drugs have different mechanisms and selection criteria.')],
 'Distinguish approval from guideline strength', '**Evidence interpretation and recommendations differ across regions.**', ['The EAN 2024 and PACTALS guidance do not make identical recommendations.','Explain expected benefit, burden and uncertainty in the local setting.'], '**Use shared decision-making.**', ['Review eligibility, administration and adverse effects.','Do not delay established supportive interventions.'], [['Riluzole','Broad recommendation'],['Edaravone','Region- and evidence-dependent'],['Tofersen','SOD1-targeted']], [EA,PA])
q('Morning headaches, orthopnea and fragmented sleep develop in ALS despite normal daytime oxygen saturation. What should be evaluated?', 'Nocturnal hypoventilation and respiratory muscle weakness',[
 ('Normal saturation excludes respiratory involvement','It does not adequately assess nocturnal ventilation.'),('Only primary insomnia without further assessment','The orthopnea and morning headache are respiratory clues.'),('The need for an antipsychotic as first-line treatment','This does not address the suspected mechanism.')],
 'Ventilation can fail first during sleep', '**ALS respiratory assessment includes symptoms and objective respiratory testing.**', ['Supine measures and inspiratory strength tests can add information.','Bulbar dysfunction can affect test reliability.'], '**Consider noninvasive ventilation when indicated.**', ['Do not wait for advanced daytime gas failure.','Discuss the patient’s goals and interface tolerance.'], [['Orthopnea','Diaphragm weakness clue'],['Morning headache','Possible nocturnal hypercapnia'],['Action','Respiratory assessment']], [EA], 'clinical_scenario')
q('What benefit can noninvasive ventilation provide in appropriately selected ALS patients?', 'Improved respiratory symptoms and quality of life, with survival benefit in suitable patients',[
 ('Regeneration of all lost motor neurons','Ventilatory support does not reverse neurodegeneration.'),('Elimination of every swallowing and secretion problem','Those require separate management.'),('No benefit unless intubation has already occurred','NIV is often introduced before invasive ventilation.')],
 'Respiratory support treats an important consequence of disease', '**NIV can reduce the burden of hypoventilation.**', ['Bulbar and secretion problems influence tolerance.','Adaptation and skilled support improve use.'], '**Review effectiveness and preferences over time.**', ['Monitor symptoms, ventilation and interface comfort.','Discuss future escalation decisions without coercion.'], [['Target','Hypoventilation'],['Benefit','Symptoms and selected survival benefit'],['Support','Interface and secretion care']], [EA])
q('A patient with ALS has a weak cough and difficulty clearing secretions. Which intervention may be appropriate?', 'Cough augmentation, including assisted cough or mechanical insufflation-exsufflation when indicated',[
 ('Oxygen alone as a complete solution to secretion retention','This does not restore cough clearance.'),('Avoid respiratory physiotherapy in every patient','Appropriate techniques can reduce complications.'),('Sedate all coughing without assessing clearance','This may worsen retention and aspiration risk.')],
 'Ventilation and clearance are separate functions', '**An effective cough requires adequate inspiratory volume and expiratory force.**', ['Bulbar dysfunction can further impair clearance.','Assess infection and aspiration when secretions increase.'], '**Individualize the airway-clearance plan.**', ['Train the patient and caregivers.','Coordinate with NIV and swallowing care.'], [['NIV','Supports ventilation'],['Cough assistance','Supports clearance'],['Bulbar function','Affects both safety and technique']], [EA], 'clinical_scenario')
q('Weight is falling in ALS because meals take too long and swallowing is unsafe. What is the best next principle?', 'Early multidisciplinary nutrition and gastrostomy discussion, considering respiratory status and the patient’s preferences',[
 ('Wait until profound respiratory failure before discussing access','Late planning can increase procedural difficulty.'),('Gastrostomy prevents every aspiration event','Saliva and reflux-related aspiration can still occur.'),('A feeding tube automatically requires stopping all pleasurable oral intake','Safe oral intake decisions are individualized.')],
 'Nutrition planning should precede a crisis', '**Dysphagia and increased effort can lead to malnutrition and dehydration.**', ['Diet modification and supplements may help earlier.','Respiratory function influences procedural planning.'], '**Explain realistic benefits and limitations.**', ['A tube supports nutrition and medication delivery.','Respect informed choice and revisit decisions as needs change.'], [['Problem','Weight loss/unsafe intake'],['Timing','Discuss early'],['Limit','Does not eliminate all aspiration']], [EA], 'clinical_scenario')
q('Drooling is troublesome in bulbar ALS. What is the most common underlying explanation?', 'Impaired swallowing and clearance of saliva rather than necessarily excessive production',[
 ('All cases are caused by a salivary-gland tumor','This is not the usual mechanism.'),('It proves an inability to produce saliva','The problem is often handling and clearance.'),('It is unrelated to bulbar function','Bulbar dysfunction is central.')],
 'Treat the handling problem and the secretion burden', '**Sialorrhea can reflect reduced clearance.**', ['Antimuscarinic strategies or salivary-gland botulinum treatment may help selected patients.','Drying treatment can thicken secretions.'], '**Balance comfort against airway clearance.**', ['Review swallowing, suction and mouth care.','Avoid creating difficult tenacious secretions without a plan.'], [['Mechanism','Impaired clearance'],['Treatment','Reduce burden when appropriate'],['Tradeoff','Thick secretions']], [EA])
q('Speech is becoming difficult in ALS while cognition and hand function remain adequate. What intervention should be introduced proactively?', 'Augmentative and alternative communication planning, including suitable assistive technology',[
 ('Wait until all communication is lost','Late introduction can reduce opportunity for training.'),('Assume dysarthria proves loss of capacity','Speech impairment and decision-making capacity differ.'),('Use sedation to reduce attempts at communication','This does not address the patient’s need.')],
 'Preserve communication before the preferred method fails', '**Voice banking and assistive systems may be easier to establish early.**', ['Options must adapt to hand and eye control.','Cognitive and language changes influence selection.'], '**Keep the patient’s choices central.**', ['Train caregivers without replacing the patient’s voice.','Reassess equipment as function changes.'], [['Timing','Proactive'],['Device choice','Match remaining abilities'],['Goal','Autonomy and participation']], [EA], 'clinical_scenario')
q('Which care model is recommended for ALS?', 'Coordinated multidisciplinary care with respiratory, nutritional, rehabilitation, communication and psychological support',[
 ('A prescription-only pathway without follow-up','ALS needs changing multidisciplinary support.'),('Palliative care only in the final hours','Symptom and goal-focused care can be helpful much earlier.'),('Avoid discussing preferences because prognosis is uncertain','Uncertainty makes supported planning important rather than irrelevant.')],
 'Disease modification and supportive care proceed together', '**A coordinated team can anticipate complications and reduce fragmented decisions.**', ['Symptoms and caregiver needs change over time.','Palliative support can coexist with active treatment.'], '**Use ongoing shared planning.**', ['Discuss ventilation, feeding and communication preferences at an appropriate pace.','Provide caregiver and bereavement resources when relevant.'], [['Team','Multiple functional domains'],['Palliative care','Can begin alongside active treatment'],['Planning','Revisited over time']], [EA])
q('A patient has progressive spastic weakness for years with no convincing LMN signs. What is an important diagnostic consideration?', 'Primary lateral sclerosis, after sufficient observation and exclusion of mimics',[
 ('Definite typical ALS from spasticity alone','The motor pattern and longitudinal findings require classification.'),('A peripheral pure motor neuropathy as the best explanation','A peripheral neuropathy does not produce a pure UMN syndrome.'),('No need for spinal imaging or other mimic assessment','Structural and other causes require exclusion.')],
 'An UMN-predominant syndrome needs time and localization', '**PLS is characterized by progressive upper motor neuron dysfunction.**', ['Some patients initially thought to have a pure UMN disorder later develop LMN evidence.','Duration and repeated assessment influence diagnostic certainty.'], '**Exclude structural, inflammatory and hereditary alternatives.**', ['Bulbar, gait and pseudobulbar symptoms need care regardless of label.','Do not offer a precise prognosis from the first examination.'], [['PLS','UMN-predominant'],['ALS','May include UMN and LMN'],['Follow-up','Clarifies evolution']], [GC,EA])
q('How should ALS prognosis be communicated?', 'Discuss the observed rate and pattern of progression, respiratory/nutritional factors and uncertainty rather than an exact individual deadline',[
 ('Give every patient the same exact survival date','Individual trajectories vary.'),('Avoid all discussion of future care','Patients may need information for planning.'),('Use one EMG amplitude as a complete prognostic model','No single measure captures the course.')],
 'Population averages do not determine an individual timeline', '**Onset pattern, progression rate, respiratory function and other factors influence outcome.**', ['Therapies and supportive choices can alter the lived course.','Preferences for information differ.'], '**Offer honest information with practical support.**', ['Revisit questions as the illness evolves.','Connect prognosis to care options without presenting uncertainty as certainty.'], [['Assessment','Several clinical factors'],['Prediction','Individual uncertainty'],['Communication','Preference-sensitive and ongoing']], [EA])

if __name__=='__main__':finalize('Neurology',9,'Motor Neuron Disease','neuro-motor-neuron',rows,24)
